const websiteCandidates = [
  $json.company_website,
  $json.official_website_scraped,
];

const rawWebsite =
  websiteCandidates.find(
    value =>
      typeof value === 'string' &&
      value.trim() !== ''
  ) || '';

let targetWebsite = rawWebsite.trim();

if (
  targetWebsite &&
  !/^[a-z][a-z0-9+.-]*:\/\//i.test(targetWebsite)
) {
  targetWebsite = `https://${targetWebsite}`;
}

return {
  json: {
    ...$json,

    target_website: targetWebsite,

    website_scan_status:
      targetWebsite
        ? 'READY'
        : 'NO_WEBSITE_FOUND',
  },
};

const company =
  $('Prepare Website Scan').item.json;

const hrefs = Array.isArray($json.hrefs)
  ? $json.hrefs
  : [];

const linkTexts = Array.isArray($json.link_texts)
  ? $json.link_texts
  : [];

const baseWebsite = String(
  company.target_website ?? ''
).trim();

const originMatch =
  baseWebsite.match(/^(https?:\/\/[^/]+)/i);

const origin = originMatch
  ? originMatch[1]
  : '';

function makeAbsoluteUrl(value) {
  const href = String(value ?? '').trim();

  if (!href) {
    return '';
  }

  if (
    href.startsWith('#') ||
    href.startsWith('mailto:') ||
    href.startsWith('tel:') ||
    href.startsWith('javascript:')
  ) {
    return '';
  }

  if (/^https?:\/\//i.test(href)) {
    return href;
  }

  if (href.startsWith('//')) {
    return `https:${href}`;
  }

  if (href.startsWith('/')) {
    return origin
      ? `${origin}${href}`
      : '';
  }

  return origin
    ? `${origin}/${href.replace(/^\/+/, '')}`
    : '';
}

const cleanedLinks = [];

for (let index = 0; index < hrefs.length; index++) {
  const url = makeAbsoluteUrl(hrefs[index]);

  if (!url) {
    continue;
  }

  const text = String(
    linkTexts[index] ?? ''
  ).trim();

  cleanedLinks.push({
    url,
    text,
    searchable_text:
      `${url} ${text}`.toLowerCase(),
  });
}

function uniqueUrls(items) {
  return [
    ...new Set(
      items.map(item => item.url)
    ),
  ];
}

const careersPattern =
  /(career|careers|job|jobs|vacanc|open[-_\s]?position|join[-_\s]?(us|our team)|work[-_\s]?with[-_\s]?us|karriere|stellen|kariera|praca|oferty[-_\s]?pracy|кариера|работа|ваканс)/i;

const contactPattern =
  /(contact|contacts|kontakt|kontak|контакт)/i;

const aboutPattern =
  /(about|our[-_\s]?company|who[-_\s]?we[-_\s]?are|our[-_\s]?story|team|people|o[-_\s]?nas|ueber[-_\s]?uns|über[-_\s]?uns|за[-_\s]?нас)/i;

const careersCandidates = uniqueUrls(
  cleanedLinks.filter(link =>
    careersPattern.test(link.searchable_text)
  )
);

const contactCandidates = uniqueUrls(
  cleanedLinks.filter(link =>
    contactPattern.test(link.searchable_text)
  )
);

const aboutCandidates = uniqueUrls(
  cleanedLinks.filter(link =>
    aboutPattern.test(link.searchable_text)
  )
);

const linkedinCandidates = uniqueUrls(
  cleanedLinks.filter(link =>
    /linkedin\.com\/company\//i.test(link.url)
  )
);

return {
  json: {
    ...company,

    homepage_links_count:
      cleanedLinks.length,

    careers_candidates:
      careersCandidates,

    careers_url:
      careersCandidates[0] || '',

    contact_candidates:
      contactCandidates,

    contact_url:
      contactCandidates[0] || '',

    about_candidates:
      aboutCandidates,

    about_url:
      aboutCandidates[0] || '',

    linkedin_candidates:
      linkedinCandidates,

    linkedin_company_url:
      linkedinCandidates[0] || '',
  },
};

const website = String(
  $json.target_website ?? ''
)
  .trim()
  .replace(/\/+$/, '');

const originMatch =
  website.match(/^(https?:\/\/[^/]+)/i);

const origin = originMatch
  ? originMatch[1]
  : '';

const discoveredCandidates =
  Array.isArray($json.careers_candidates)
    ? $json.careers_candidates
    : [];

const commonPaths = [
  '/careers',
  '/jobs',
  '/career',
  '/join-us',
  '/join-our-team',
  '/work-with-us',
  '/karriere',
  '/kariera',
  '/praca',
];

const generatedCandidates = origin
  ? commonPaths.map(path => `${origin}${path}`)
  : [];

const careerProbeUrls = (
  discoveredCandidates.length > 0
    ? discoveredCandidates
    : generatedCandidates
)
  .map(value =>
    String(value ?? '')
      .trim()
      .replace(/#.*$/, '')
  )
  .filter(Boolean);

const uniqueCareerProbeUrls = [
  ...new Set(careerProbeUrls),
];

return {
  json: {
    ...$json,

    career_probe_urls:
      uniqueCareerProbeUrls,

    career_probe_count:
      uniqueCareerProbeUrls.length,
  },
};

const source =
  $('Split Career Candidates').item.json;

const probeUrl = String(
  source.career_probe_urls ?? ''
).trim();

const statusCode = Number(
  $json.statusCode ??
  $json.status_code ??
  0
);

const rawHtml = String(
  $json.career_page_html ??
  $json.body?.career_page_html ??
  $json.body ??
  ''
);

const pageText = rawHtml
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

const notFoundPattern =
  /(404|page not found|not found|does not exist|doesn't exist|seite nicht gefunden|strona nie istnieje)/i;

const careersPattern =
  /(career|careers|jobs|job openings|open positions|join our team|work with us|vacancies|karriere|stellenangebote|kariera|oferty pracy|работа|вакансии)/i;

const applicationPattern =
  /(apply|application|position|role|vacancy|opening|candidate|recruitment|submit your cv|send your cv)/i;

const statusOkay =
  statusCode >= 200 &&
  statusCode < 400;

const hasNotFoundSignal =
  notFoundPattern.test(pageText);

const hasCareerSignal =
  careersPattern.test(pageText);

const hasApplicationSignal =
  applicationPattern.test(pageText);

let probeStatus = 'NO_CAREER_SIGNAL';

if (statusCode === 404 || statusCode === 410) {
  probeStatus = 'NOT_FOUND';
} else if (statusCode === 401 || statusCode === 403) {
  probeStatus = 'BLOCKED';
} else if (statusCode === 0 || statusCode >= 500) {
  probeStatus = 'HTTP_ERROR';
} else if (!statusOkay) {
  probeStatus = 'HTTP_ERROR';
} else if (hasNotFoundSignal && !hasCareerSignal) {
  probeStatus = 'NOT_FOUND';
} else if (hasCareerSignal && hasApplicationSignal) {
  probeStatus = 'LIKELY_CAREERS_PAGE';
} else if (hasCareerSignal) {
  probeStatus = 'POSSIBLE_CAREERS_PAGE';
}

return {
  json: {
    ...source,

    career_probe_url: probeUrl,
    career_probe_status_code: statusCode,
    career_probe_status: probeStatus,

    career_signal_found:
      hasCareerSignal,

    application_signal_found:
      hasApplicationSignal,

    page_not_found_signal:
      hasNotFoundSignal,

    career_page_text_preview:
      pageText.slice(0, 500),
  },
};

const rows = $input.all().map(item => item.json);

const groups = new Map();

for (const row of rows) {
  const key =
    row.company_key ||
    row.company_domain ||
    row.company_name ||
    'unknown-company';

  if (!groups.has(key)) {
    groups.set(key, []);
  }

  groups.get(key).push(row);
}

const ranking = {
  LIKELY_CAREERS_PAGE: 5,
  POSSIBLE_CAREERS_PAGE: 4,
  NO_CAREER_SIGNAL: 2,
  NOT_FOUND: 1,
  BLOCKED: 0,
  HTTP_ERROR: 0,
};

const output = [];

for (const [companyKey, probes] of groups.entries()) {
  const sortedProbes = [...probes].sort((a, b) => {
    const scoreA =
      ranking[a.career_probe_status] ?? 0;

    const scoreB =
      ranking[b.career_probe_status] ?? 0;

    return scoreB - scoreA;
  });

  const bestProbe = sortedProbes[0];

  const hasLikelyPage = probes.some(
    probe =>
      probe.career_probe_status ===
      'LIKELY_CAREERS_PAGE'
  );

  const hasPossiblePage = probes.some(
    probe =>
      probe.career_probe_status ===
      'POSSIBLE_CAREERS_PAGE'
  );

  const allHttpErrors = probes.every(
    probe =>
      probe.career_probe_status ===
      'HTTP_ERROR'
  );

  let careersPageStatus =
    'CAREERS_PAGE_NOT_FOUND';

  if (hasLikelyPage) {
    careersPageStatus =
      'CAREERS_PAGE_FOUND';
  } else if (hasPossiblePage) {
    careersPageStatus =
      'CAREERS_PAGE_POSSIBLE';
  } else if (allHttpErrors) {
    careersPageStatus =
      'CAREERS_PAGE_UNREACHABLE';
  }

  const acceptedStatuses = [
    'LIKELY_CAREERS_PAGE',
    'POSSIBLE_CAREERS_PAGE',
  ];

  const selectedCareersUrl =
    acceptedStatuses.includes(
      bestProbe.career_probe_status
    )
      ? bestProbe.career_probe_url
      : '';

  const base = {
    ...probes[0],
  };

  delete base.career_probe_url;
  delete base.career_probe_status_code;
  delete base.career_probe_status;
  delete base.career_signal_found;
  delete base.application_signal_found;
  delete base.page_not_found_signal;
  delete base.career_page_text_preview;

  output.push({
    json: {
      ...base,

      company_key: companyKey,

      careers_url:
        selectedCareersUrl,

      careers_page_status:
        careersPageStatus,

      career_probe_count:
        probes.length,

      career_probe_results:
        probes.map(probe => ({
          url:
            probe.career_probe_url,

          status_code:
            probe.career_probe_status_code,

          result:
            probe.career_probe_status,
        })),
    },
  });
}

return output;

const entityType = String(
  $json.entity_type ?? ''
).toUpperCase();

const countryStatus = String(
  $json.country_match_status ?? ''
).toUpperCase();

const profileFitScore = Number(
  $json.profile_fit_score ?? 0
);

const hiringSignal =
  $json.hiring_signal === true ||
  String($json.hiring_signal).toLowerCase() === 'true';

let opportunityType = 'SPECULATIVE_OUTREACH';

if (
  entityType === 'VC_FUND' ||
  entityType === 'ACCELERATOR'
) {
  opportunityType = 'ECOSYSTEM_OUTREACH';
} else if (countryStatus === 'MISMATCH') {
  opportunityType = 'MONITOR_ONLY';
}

const qualificationReasonParts = [
  'No public careers page was found.',
];

if ($json.profile_fit_evidence) {
  qualificationReasonParts.push(
    String($json.profile_fit_evidence)
  );
}

if ($json.hiring_evidence) {
  qualificationReasonParts.push(
    String($json.hiring_evidence)
  );
}

return {
  json: {
    ...$json,

    qualification_path:
      'NO_CAREERS_PAGE',

    openings_count: 0,
    relevant_openings_count: 0,

    relevant_role_titles: [],
    relevant_vacancy_urls: [],

    vacancy_status:
      $json.careers_page_status ===
      'CAREERS_PAGE_UNREACHABLE'
        ? 'UNKNOWN'
        : 'CAREERS_PAGE_NOT_FOUND',

    english_workplace_evidence: '',

    relocation_support_status:
      'UNKNOWN',

    relocation_evidence: '',

    visa_support_status:
      $json.visa_support_status ||
      'UNKNOWN',

    visa_evidence:
      $json.visa_sponsorship_evidence ||
      '',

    opportunity_type:
      opportunityType,

    qualification_score:
      Math.min(
        100,
        profileFitScore +
          (hiringSignal ? 5 : 0)
      ),

    qualification_reason:
      qualificationReasonParts.join(' '),

    qualification_status:
      'QUALIFIED',

    last_checked:
      new Date().toISOString(),

    qualification_version: 3,
  },
};

let company;

try {
  // Normal path: the careers page was discovered during this run
  company =
    $('Has Careers Page?').item.json;
} catch {
  // Shortcut path: a previously saved careers URL was reused
  company =
    $('Has Saved Careers URL?').item.json;
}
const hrefs = Array.isArray($json.hrefs)
  ? $json.hrefs
  : [];

const linkTexts = Array.isArray($json.link_texts)
  ? $json.link_texts
  : [];

const mailtoLinks = Array.isArray($json.mailto_links)
  ? $json.mailto_links
  : [];

const baseWebsite = String(
  company.careers_url ||
  company.target_website ||
  ''
)
  .trim()
  .replace(/\/+$/, '');

const originMatch =
  baseWebsite.match(/^(https?:\/\/[^/]+)/i);

const origin = originMatch
  ? originMatch[1]
  : '';

function makeAbsoluteUrl(value) {
  const href = String(value ?? '').trim();

  if (!href || href.startsWith('#')) {
    return '';
  }

  if (/^https?:\/\//i.test(href)) {
    return href;
  }

  if (href.startsWith('//')) {
    return `https:${href}`;
  }

  if (href.startsWith('/')) {
    return origin
      ? `${origin}${href}`
      : '';
  }

  return origin
    ? `${origin}/${href.replace(/^\/+/, '')}`
    : '';
}

function cleanText(value) {
  return String(value ?? '')
    .replace(/\[[^\]]+\]/g, ' ')
    .replace(/[→›»]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const jobPathPattern =
  /\/(career|careers|job|jobs|position|positions|vacancy|vacancies)\/[^/?#]+/i;

const knownAtsPattern =
  /(lever\.co|greenhouse\.io|workable\.com|recruitee\.com|teamtailor\.com|smartrecruiters\.com|workdayjobs\.com)/i;

const excludedRolePattern =
  /(sales|marketing|marketer|sdr|business development|account executive|customer success|recruiter|recruitment|human resources|finance|legal)/i;

const targetRolePattern =
  /(artificial intelligence engineer|ai engineer|machine learning engineer|\bml engineer\b|data engineer|data scientist|analytics engineer|mlops|research scientist|applied scientist|nlp engineer|computer vision engineer|deep learning engineer|backend engineer|backend developer|platform engineer|infrastructure engineer|software engineer|full[-\s]?stack engineer|python developer|python engineer)/i;

const openings = [];

for (let index = 0; index < hrefs.length; index++) {
  const url = makeAbsoluteUrl(hrefs[index]);
  const title = cleanText(linkTexts[index]);

  if (!url) {
    continue;
  }

  const isJobLink =
    jobPathPattern.test(url) ||
    knownAtsPattern.test(url);

  const isGenericCareersPage =
    /\/(career|careers|job|jobs|position|positions|vacancy|vacancies)\/?(?:[?#].*)?$/i
      .test(url);

  if (!isJobLink || isGenericCareersPage) {
    continue;
  }

  openings.push({
    title: title || 'Untitled position',
    url,
    relevant:
      !excludedRolePattern.test(title) &&
      targetRolePattern.test(title),
  });
}

const uniqueOpenings = [
  ...new Map(
    openings.map(opening => [
      opening.url,
      opening,
    ])
  ).values(),
];

const relevantOpenings =
  uniqueOpenings.filter(
    opening => opening.relevant
  );

const extractedEmails = [
  ...new Set(
    mailtoLinks
      .map(value =>
        String(value ?? '')
          .replace(/^mailto:/i, '')
          .split('?')[0]
          .trim()
          .toLowerCase()
      )
      .filter(Boolean)
  ),
];

const excludedEmailPattern =
  /^(sales|marketing|support|billing|privacy|security|press|media|legal|partnerships?|business)@/i;

function emailPriority(email) {
  if (
    /^(careers?|jobs?|recruiting|recruitment|talent|hr|people)@/i
      .test(email)
  ) {
    return 3;
  }

  if (
    /^(info|hello|contact|office|team)@/i
      .test(email)
  ) {
    return 2;
  }

  return 1;
}

const suitableEmails = extractedEmails
  .filter(email =>
    !excludedEmailPattern.test(email)
  )
  .sort(
    (a, b) =>
      emailPriority(b) -
      emailPriority(a)
  );

const careersContactEmail =
  suitableEmails[0] || '';
return {
  json: {
    ...company,

    openings_count:
      uniqueOpenings.length,

    opening_titles:
      uniqueOpenings.map(
        opening => opening.title
      ),

    opening_urls:
      uniqueOpenings.map(
        opening => opening.url
      ),

    relevant_openings_count:
      relevantOpenings.length,

    relevant_role_titles:
      relevantOpenings.map(
        opening => opening.title
      ),

    relevant_vacancy_urls:
      relevantOpenings.map(
        opening => opening.url
      ),

    careers_contact_email:
      careersContactEmail,

    extracted_openings:
      uniqueOpenings,
  },
};

const entityType = String(
  $json.entity_type ?? ''
).toUpperCase();

const countryStatus = String(
  $json.country_match_status ?? ''
).toUpperCase();

const profileFitScore = Number(
  $json.profile_fit_score ?? 0
);

const openingsCount = Number(
  $json.openings_count ?? 0
);

const relevantOpeningsCount = Number(
  $json.relevant_openings_count ?? 0
);

const hiringSignal =
  $json.hiring_signal === true ||
  String($json.hiring_signal ?? '')
    .toLowerCase() === 'true';

const relevantTitles = Array.isArray(
  $json.relevant_role_titles
)
  ? $json.relevant_role_titles
  : [];

const relevantUrls = Array.isArray(
  $json.relevant_vacancy_urls
)
  ? $json.relevant_vacancy_urls
  : [];

let vacancyStatus = 'NO_OPENINGS_FOUND';

if (relevantOpeningsCount > 0) {
  vacancyStatus = 'RELEVANT_OPENING';
} else if (openingsCount > 0) {
  vacancyStatus = 'OTHER_OPENINGS';
}

let opportunityType = 'SPECULATIVE_OUTREACH';

if (countryStatus === 'MISMATCH') {
  opportunityType = 'MONITOR_ONLY';
} else if (
  entityType === 'VC_FUND' ||
  entityType === 'ACCELERATOR'
) {
  opportunityType = 'ECOSYSTEM_OUTREACH';
} else if (relevantOpeningsCount > 0) {
  opportunityType = 'DIRECT_APPLICATION';
} else if (
  openingsCount === 0 &&
  profileFitScore < 50 &&
  !hiringSignal
) {
  opportunityType = 'MONITOR_ONLY';
}

let qualificationScore = profileFitScore;

if (relevantOpeningsCount > 0) {
  qualificationScore += 15;
} else if (openingsCount > 0) {
  qualificationScore += 5;
}

if (hiringSignal) {
  qualificationScore += 5;
}

qualificationScore = Math.min(
  100,
  qualificationScore
);

const qualificationReasonParts = [];

if (relevantOpeningsCount > 0) {
  qualificationReasonParts.push(
    `${relevantOpeningsCount} relevant public opening(s) found: ${relevantTitles.join(' | ')}.`
  );
} else if (openingsCount > 0) {
  qualificationReasonParts.push(
    `${openingsCount} public opening(s) found, but none matched the target AI/Data profile.`
  );
} else {
  qualificationReasonParts.push(
    'A careers page was found, but no active openings were detected.'
  );
}

if ($json.profile_fit_evidence) {
  qualificationReasonParts.push(
    String($json.profile_fit_evidence)
  );
}

return {
  json: {
    ...$json,

    relevant_role_titles:
      relevantTitles.join(' | '),

    relevant_vacancy_urls:
      relevantUrls.join(' | '),

    vacancy_status:
      vacancyStatus,

    opportunity_type:
      opportunityType,

    english_workplace_evidence: '',

    relocation_support_status:
      'UNKNOWN',

    relocation_evidence: '',

    visa_support_status:
      $json.visa_support_status ||
      'UNKNOWN',

    visa_evidence:
      $json.visa_sponsorship_evidence ||
      '',

    qualification_score:
      qualificationScore,

    qualification_reason:
      qualificationReasonParts.join(' '),

    qualification_status:
      'QUALIFIED',

    last_checked:
      new Date().toISOString(),

    qualification_version: 3,
  },
};

function normalizeKey(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase();
}


// Companies already present in Company_Qualification
const existingKeys = new Set(
  $('Load Existing Qualifications')
    .all()
    .map(item =>
      normalizeKey(item.json.company_key)
    )
    .filter(Boolean)
);


const inputs = $input.all();

const seenThisRun = new Set();
const output = [];

for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i];

  const key = normalizeKey(
    item.json.company_key
  );

  if (!key) {
    continue;
  }

  // Already qualified previously
  if (existingKeys.has(key)) {
    continue;
  }

  // Duplicate candidate in this execution
  if (seenThisRun.has(key)) {
    continue;
  }

  seenThisRun.add(key);

  output.push({
    json: {
      ...item.json,
    },
    pairedItem: {
      item: i,
    },
  });
}

return output;
